/* LOS SABERES DE CADA ÉPOCA SE DERIVAN DE LA FICHA ÚNICA: cada entrada ya declara su era (y su edad,
   en la Época 1: 1 el fogón, 2 la aldea) y si es manual (el fuego, que no se compra). Antes estas
   listas vivían copiadas como índices en tick(), la consejera, el guardado y la interfaz; ahora salen
   todas de aquí. Sin edad devuelve la época entera. El ORDEN de oferta es otra cosa: ORDEN_* en 14. */
function saberesEpoca(era, edad) {
  return BALANCE.tecnologias.map((T, i) => ({ T, i }))
    .filter(x => (x.T.era || 11) === era && !x.T.manual && (edad === undefined || (x.T.edad || 1) === edad))
    .map(x => x.i);
}

